    (85, 've_eaeac5a4c3', 'Restaurant Mont-Rouge', 'Mont-Rouge', 'michelin', 'https://guide.michelin.com/us/en/wallis/haute-nendaz/restaurant/mont-rouge', 'CH name-diff evidence line 97; live "Restaurant Mont-Rouge"; card h1 "Mont-Rouge"; site read: logo "Restaurant Mont-Rouge"; body "Mont-Rouge"; rule R2; Michelin card https://guide.michelin.com/us/en/wallis/haute-nendaz/restaurant/mont-rouge; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (86, 've_cd936acefb', 'Ristorante Asia', 'Asia', 'michelin', 'https://guide.michelin.com/us/en/ticino/ascona/restaurant/asia', 'CH name-diff evidence line 98; live "Ristorante Asia"; card h1 "Asia"; site read: group page, no Asia name; not read; rule R5; Michelin card https://guide.michelin.com/us/en/ticino/ascona/restaurant/asia; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (87, 've_787c43dc24', 'netts', 'Netts Schützengarten', 'michelin', 'https://guide.michelin.com/us/en/sankt-gallen-region/sankt-gallen/restaurant/netts-schutzengarten', 'CH name-diff evidence line 99; live "netts"; card h1 "Netts Schützengarten"; site read: Ben rejected the prompt; not read; rule R5; Michelin card https://guide.michelin.com/us/en/sankt-gallen-region/sankt-gallen/restaurant/netts-schutzengarten; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (88, 've_016ad6629e', 'Gül Restoran', 'Gül', 'michelin', 'https://guide.michelin.com/us/en/zurich-region/zurich/restaurant/gul', 'CH name-diff evidence line 100; live "Gül Restoran"; card h1 "Gül"; site read: logo "GÜL"; body "Gül"; contact "Gül Restoran AG"; rule R2; Michelin card https://guide.michelin.com/us/en/zurich-region/zurich/restaurant/gul; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (89, 've_85ddc8ee73', 'MYŌ Sushi Bar', 'MYO Sushi Bar', 'venue', 'https://www.myo.ch/', 'CH name-diff evidence line 101; live "MYŌ Sushi Bar"; card h1 "Myò Sushi Bar"; site read: title "MYO Sushi Bar Lausanne"; logo MYO; rule R1; Michelin card https://guide.michelin.com/us/en/vaud/lausanne/restaurant/myo-sushi-bar; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (90, 've_9d2037d9e3', 'Landgasthaus Bären Grub', 'Bären', 'michelin', 'https://guide.michelin.com/us/en/appenzell-ausserrhoden/grub/restaurant/baren179308', 'CH name-diff evidence line 102; live "Landgasthaus Bären Grub"; card h1 "Bären"; site read: prompt not answered; not read; rule R5; Michelin card https://guide.michelin.com/us/en/appenzell-ausserrhoden/grub/restaurant/baren179308; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (91, 've_4b848ba4c5', 'Eintracht Restaurant + Catering', 'Eintracht', 'michelin', 'https://guide.michelin.com/us/en/solothurn-region/kestenholz/restaurant/eintracht', 'CH name-diff evidence line 103; live "Eintracht Restaurant + Catering"; card h1 "Eintracht"; site read: prompt not answered; not read; rule R5; Michelin card https://guide.michelin.com/us/en/solothurn-region/kestenholz/restaurant/eintracht; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (92, 've_0453a355cc', '16 ART-BAR-RESTAURANT SAANEN', '16 ART-BAR-RESTAURANT', 'michelin', 'https://guide.michelin.com/us/en/bern-region/saanen/restaurant/16-art-bar', 'CH name-diff evidence line 104; live "16 ART-BAR-RESTAURANT SAANEN"; card h1 "16 ART-BAR-RESTAURANT"; site read: "16 ART-BAR-RESTAURANT", sometimes with SAANEN; rule R2; Michelin card https://guide.michelin.com/us/en/bern-region/saanen/restaurant/16-art-bar; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (93, 've_3b661056f4', 'Hotel Balm', 'Balm-Bistro', 'venue', 'https://www.balm.ch', 'CH name-diff evidence line 106; live "Hotel Balm"; card h1 "Balm - Bistro"; site read: "Balm-Bistro" or "Bistro"; rule R1; Michelin card https://guide.michelin.com/us/en/luzern-region/meggen/restaurant/la-pistache-bistro; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"'),
    (94, 've_1eed8640fe', 'Restaurant Curiades', 'Les Curiades', 'michelin', 'https://guide.michelin.com/us/en/geneve-region/bernex/restaurant/les-curiades', 'CH name-diff evidence line 107; live "Restaurant Curiades"; card h1 "Les Curiades"; site read: "Les Curiades"; rule R1; Michelin card https://guide.michelin.com/us/en/geneve-region/bernex/restaurant/les-curiades; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"')
  ) AS t(line, venue_id, expected_name, new_name, source_id, source_url, note);

  SELECT count(*), count(DISTINCT p.venue_id) INTO n, x FROM jsonb_to_recordset(plan) p(venue_id text);
  IF n <> 94 OR x <> 94 THEN RAISE EXCEPTION 'input rows % / distinct venues % (expected 94 / 94)', n, x; END IF;
  IF (SELECT md5(string_agg(p.venue_id||'|'||p.expected_name, E'\n' ORDER BY p.venue_id))
        FROM jsonb_to_recordset(plan) p(venue_id text, expected_name text)) <> 'eb67c3225d3ce818f233e5d43312be1a' THEN
    RAISE EXCEPTION 'input guard id|expected_name failed'; END IF;
  IF (SELECT md5(string_agg(p.venue_id||'|'||p.new_name, E'\n' ORDER BY p.venue_id))
        FROM jsonb_to_recordset(plan) p(venue_id text, new_name text)) <> '36ea880a01a9bdbf59abd204e9b30efd' THEN
    RAISE EXCEPTION 'input guard id|new_name failed'; END IF;
  IF (SELECT md5(string_agg(p.line||'|'||p.venue_id||'|'||p.expected_name||'|'||p.new_name||'|'||p.source_id||'|'||p.source_url,
                            E'\n' ORDER BY p.venue_id))
        FROM jsonb_to_recordset(plan) p(line int, venue_id text, expected_name text, new_name text, source_id text, source_url text))
       <> '63e789ccc7cd2235380e03c76bce27a7' THEN
    RAISE EXCEPTION 'input guard rows failed'; END IF;
  IF (SELECT md5(string_agg(p.venue_id||'|'||p.note, E'\n' ORDER BY p.venue_id))
        FROM jsonb_to_recordset(plan) p(venue_id text, note text)) <> 'e49d717e03d1cbbe36bb57a8148b80de' THEN
    RAISE EXCEPTION 'input guard notes failed'; END IF;

  -- 2. Pre-checks against live data
  SELECT count(*) INTO x FROM rename_batches WHERE batch_key = 'rename-michelin-2026-switzerland';
  IF x <> 0 THEN RAISE EXCEPTION 'batch key already used: %', x; END IF;

  IF (SELECT md5(string_agg(v.id||'|'||v.name, E'\n' ORDER BY v.id))
        FROM venues v JOIN jsonb_to_recordset(plan) p(venue_id text) ON p.venue_id = v.id) <> 'eb67c3225d3ce818f233e5d43312be1a' THEN
    RAISE EXCEPTION 'live names differ from the Nov 3 04:29 UTC read (a name moved)'; END IF;

  SELECT count(*) INTO x FROM venues v JOIN jsonb_to_recordset(plan) p(venue_id text) ON p.venue_id = v.id
   WHERE v.status = 'active';
  IF x <> 94 THEN RAISE EXCEPTION 'active venues % (expected 94)', x; END IF;

  SELECT count(*) INTO x FROM jsonb_to_recordset(plan) p(new_name text, expected_name text)
   WHERE btrim(p.new_name) = '' OR p.new_name <> btrim(p.new_name) OR p.new_name = p.expected_name;
  IF x <> 0 THEN RAISE EXCEPTION 'empty, untrimmed or unchanged new names: %', x; END IF;

  SELECT count(*) INTO x FROM jsonb_to_recordset(plan) p(source_id text) WHERE p.source_id NOT IN ('michelin', 'venue');
  IF x <> 0 THEN RAISE EXCEPTION 'unexpected source_id: %', x; END IF;
  SELECT count(*) INTO x FROM jsonb_to_recordset(plan) p(source_id text) WHERE p.source_id = 'michelin';
  IF x <> 81 THEN RAISE EXCEPTION 'michelin rows % (expected 81)', x; END IF;
  SELECT count(*) INTO x FROM award_sources WHERE slug = 'michelin';
  IF x <> 1 THEN RAISE EXCEPTION 'michelin not registered in award_sources'; END IF;
  SELECT count(*) INTO x FROM award_sources WHERE slug = 'venue';
  IF x <> 0 THEN RAISE EXCEPTION 'venue is a registered source (ledger rule changes)'; END IF;
  SELECT count(*) INTO x FROM jsonb_to_recordset(plan) p(source_url text)
   WHERE p.source_url !~ '^https://' OR p.source_url ~* '(joinpearl|thebestrestaurantsguide|beliapp)';
  IF x <> 0 THEN RAISE EXCEPTION 'bad source_url: %', x; END IF;

  SELECT count(*) INTO x FROM rename_rows r JOIN jsonb_to_recordset(plan) p(venue_id text) ON p.venue_id = r.venue_id;
  IF x <> 0 THEN RAISE EXCEPTION 'earlier rename_rows on these venues: %', x; END IF;

  -- same-city norm_key collisions on the end state (scripts/rename/lib/impact.ts rule)
  WITH batch AS (SELECT p.venue_id, p.new_name FROM jsonb_to_recordset(plan) p(venue_id text, new_name text)),
       scope AS (SELECT DISTINCT v.city_id FROM venues v JOIN batch b ON b.venue_id = v.id),
       fin   AS (SELECT v.id, v.city_id, coalesce(b.new_name, v.name) AS name
                   FROM venues v JOIN scope s ON s.city_id = v.city_id LEFT JOIN batch b ON b.venue_id = v.id)
  SELECT count(*) INTO x FROM fin a JOIN batch ON batch.venue_id = a.id
    JOIN fin o ON o.city_id = a.city_id AND o.id <> a.id
              AND norm_key(a.name) IS NOT NULL AND norm_key(o.name) = norm_key(a.name);
  IF x <> 0 THEN RAISE EXCEPTION 'same-city norm_key collisions: %', x; END IF;

  SELECT count(*) INTO x FROM jsonb_to_recordset(plan) p(venue_id text)
   WHERE (SELECT count(*) FROM slugs s WHERE s.venue_id = p.venue_id AND s.property_id = 'eats' AND s.is_canonical) <> 1;
  IF x <> 0 THEN RAISE EXCEPTION 'venues without exactly 1 canonical slug: %', x; END IF;

  SELECT count(*) INTO x FROM blurbs b JOIN jsonb_to_recordset(plan) p(venue_id text) ON p.venue_id = b.venue_id;
  IF x <> 0 THEN RAISE EXCEPTION 'blurbs on batch venues % (expected 0)', x; END IF;

  SELECT count(*) INTO x FROM venues;          IF x <> 11323 THEN RAISE EXCEPTION 'venues before % (expected 11323)', x; END IF;
  SELECT count(*) INTO x FROM awards;          IF x <> 25321 THEN RAISE EXCEPTION 'awards before % (expected 25321)', x; END IF;
  SELECT count(*) INTO x FROM slugs;           IF x <> 13053 THEN RAISE EXCEPTION 'slugs before % (expected 13053)', x; END IF;
  SELECT count(*) INTO x FROM listings;        IF x <> 11323 THEN RAISE EXCEPTION 'listings before % (expected 11323)', x; END IF;
  SELECT count(*) INTO x FROM blurbs;          IF x <> 142 THEN RAISE EXCEPTION 'blurbs before % (expected 142)', x; END IF;
  SELECT count(*) INTO x FROM rename_batches;  IF x <> 30 THEN RAISE EXCEPTION 'rename_batches before % (expected 30)', x; END IF;
  SELECT count(*) INTO x FROM rename_rows;     IF x <> 1302 THEN RAISE EXCEPTION 'rename_rows before % (expected 1302)', x; END IF;
  SELECT count(*), max(id) INTO led_n, led_max FROM source_capture_ledger;
  IF led_n <> 189 OR led_max <> 243 THEN RAISE EXCEPTION 'ledger before % rows, last id % (expected 189, 243)', led_n, led_max; END IF;
  SELECT count(*), max(id) INTO aud_n, aud_max FROM audit_log;
  IF aud_n <> 119235 OR aud_max <> 125064 THEN
    RAISE EXCEPTION 'audit_log before % rows, last id % (expected 119235, 125064)', aud_n, aud_max; END IF;

  -- 3. Writes (same order as the rename job)
  INSERT INTO rename_batches (batch_key, status, note)
  VALUES ('rename-michelin-2026-switzerland', 'staged', 'Swiss 2026 name differences (Michelin 2026 card read and venue-site read Nov 2 2026, evidence file docs/ch-2026-build/name-diff-evidence-ch-2026-11-02.csv): 94 of 107 rename, 12 keep, 1 hold; item 1 of the Swiss open items; Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"')
  RETURNING id INTO bid;

  INSERT INTO rename_rows (batch_id, line, venue_id, expected_name, new_name, source_id, source_url, verdict, detail)
  SELECT bid, p.line, p.venue_id, p.expected_name, p.new_name, p.source_id, p.source_url, 'rename',
         jsonb_build_object('note', p.note, 'live_name', v.name, 'city_id', v.city_id,
                            'city_slug', s.city_slug, 'slug', s.slug)
    FROM jsonb_to_recordset(plan) p(line int, venue_id text, expected_name text, new_name text,
                                    source_id text, source_url text, note text)
    JOIN venues v ON v.id = p.venue_id
    JOIN slugs  s ON s.venue_id = v.id AND s.property_id = 'eats' AND s.is_canonical;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 94 THEN RAISE EXCEPTION 'rename_rows inserted % (expected 94)', n; END IF;

  PERFORM set_config('app.allow_rename', 'on', true);
  UPDATE venues v SET name = p.new_name
    FROM jsonb_to_recordset(plan) p(venue_id text, expected_name text, new_name text)
   WHERE v.id = p.venue_id AND v.name = p.expected_name;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM set_config('app.allow_rename', 'off', true);
  IF n <> 94 THEN RAISE EXCEPTION 'venues renamed % (expected 94)', n; END IF;

  INSERT INTO source_capture_ledger (publisher, field_type, items, job)
  VALUES ('michelin', 'name', 81, 'rename-apply:rename-michelin-2026-switzerland | gated SQL file docs/rename-michelin-2026-switzerland.sql (Write connector), same writes as the job | 81 rows source michelin, 13 rows source venue write no ledger row | Ben Nov 2 23:04 ET "1&4", 23:25 ET "A"');

  UPDATE rename_batches SET status = 'applied', applied_at = now() WHERE id = bid AND status = 'staged';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'batch status update % (expected 1)', n; END IF;

  -- 4. Post-checks (the job's invariants)
  SELECT count(*) INTO x FROM venues v JOIN jsonb_to_recordset(plan) p(venue_id text, new_name text) ON p.venue_id = v.id
   WHERE v.name IS DISTINCT FROM p.new_name;
  IF x <> 0 THEN RAISE EXCEPTION 'venues whose live name is not new_name: %', x; END IF;
  IF (SELECT md5(string_agg(v.id||'|'||v.name, E'\n' ORDER BY v.id))
        FROM venues v JOIN jsonb_to_recordset(plan) p(venue_id text) ON p.venue_id = v.id) <> '36ea880a01a9bdbf59abd204e9b30efd' THEN
    RAISE EXCEPTION 'live id|name after differs from the file'; END IF;

  SELECT count(*) INTO x FROM venues;          IF x <> 11323 THEN RAISE EXCEPTION 'venues changed: %', x; END IF;
  SELECT count(*) INTO x FROM awards;          IF x <> 25321 THEN RAISE EXCEPTION 'awards changed: %', x; END IF;
  SELECT count(*) INTO x FROM slugs;           IF x <> 13053 THEN RAISE EXCEPTION 'slugs changed: %', x; END IF;
  SELECT count(*) INTO x FROM listings;        IF x <> 11323 THEN RAISE EXCEPTION 'listings changed: %', x; END IF;
  SELECT count(*) INTO x FROM blurbs;          IF x <> 142 THEN RAISE EXCEPTION 'blurbs changed: %', x; END IF;
  SELECT count(*) INTO x FROM rename_batches;  IF x <> 31 THEN RAISE EXCEPTION 'rename_batches after % (expected 31)', x; END IF;
  SELECT count(*) INTO x FROM rename_rows;     IF x <> 1396 THEN RAISE EXCEPTION 'rename_rows after % (expected 1396)', x; END IF;
  SELECT count(*) INTO x FROM rename_rows WHERE batch_id = bid AND verdict = 'rename';
  IF x <> 94 THEN RAISE EXCEPTION 'rename_rows in this batch % (expected 94)', x; END IF;
  SELECT count(*) INTO x FROM source_capture_ledger;
  IF x <> 190 THEN RAISE EXCEPTION 'ledger after % (expected 190)', x; END IF;
  SELECT count(*) INTO x FROM source_capture_ledger
   WHERE id > led_max AND publisher = 'michelin' AND field_type = 'name' AND items = 81 AND job LIKE 'rename-apply:rename-michelin-2026-switzerland |%';
  IF x <> 1 THEN RAISE EXCEPTION 'ledger row for this batch % (expected 1)', x; END IF;

  SELECT count(*) INTO x FROM audit_log WHERE id > aud_max;
  IF x <> 94 THEN RAISE EXCEPTION 'audit rows this transaction % (expected 94)', x; END IF;
  SELECT count(*) INTO x FROM audit_log a JOIN jsonb_to_recordset(plan) p(venue_id text, expected_name text, new_name text)
      ON a.row_pk = p.venue_id
   WHERE a.id > aud_max AND a.table_name = 'venues' AND a.action = 'UPDATE' AND a.at = transaction_timestamp()
     AND a.old_row->>'name' = p.expected_name AND a.new_row->>'name' = p.new_name
     AND (a.old_row - 'name' - 'norm_key') = (a.new_row - 'name' - 'norm_key');
  IF x <> 94 THEN RAISE EXCEPTION 'audit venue renames (name and norm_key only) % (expected 94)', x; END IF;
END
$do$;
COMMIT;
